"""Output definitions for P7 Fill Semantics."""

from __future__ import annotations


PHASE_ID = "P7"


SPO_SCHEMA = {
    "fill_mode": {
        "description": "The selected fill mode: none, previous, linear, or constant.",
        "source_actions": ["P7A1"],
    },
    "fill_parameter": {
        "description": "The generated PREVIOUS threshold or constant fill value.",
        "source_actions": ["P7A2"],
    },
    "fill_clause": {
        "description": "The concrete FILL clause generated by P7A2.",
        "source_actions": ["P7A2"],
    },
}


ACTION_TO_SPO_FIELD = {
    "P7A1": "fill_mode",
    "P7A2": "fill_parameter",
}


FLAG_SCHEMA = {
    "has_fill": {
        "description": "Whether the query uses a FILL clause.",
        "source_actions": ["P7A1"],
    },
    "fill_parameter_required": {
        "description": "Whether the selected fill mode requires parameter instantiation.",
        "source_actions": ["P7A1"],
    },
    "fill_clause_ready": {
        "description": "Whether a concrete FILL clause is ready in QueryFrame.",
        "source_actions": ["P7A1", "P7A2"],
    },
}


def has_spo_update(action_id: str) -> bool:
    return action_id in ACTION_TO_SPO_FIELD


def build_spo_delta(action_id: str, selected_action: str | None) -> dict:
    field = ACTION_TO_SPO_FIELD.get(action_id)
    return {PHASE_ID: {field: selected_action}} if field else {}


def has_flag_update(action_id: str) -> bool:
    return action_id in {"P7A1", "P7A2"}


def build_flag_delta(action_id: str, selected_action: str | None) -> dict:
    if action_id == "P7A1":
        return {
            "has_fill": selected_action != "none",
            "fill_parameter_required": selected_action in {"previous", "constant"},
            "fill_clause_ready": selected_action == "none",
        }
    if action_id == "P7A2":
        return {
            "has_fill": True,
            "fill_clause_ready": True,
        }
    return {}


def build_phase_spo_delta(phase_spo: dict, skill_outputs: list[dict]) -> dict:
    return {
        PHASE_ID: {
            field: phase_spo.get(field)
            for field in SPO_SCHEMA
        }
    }
